"""Macht aus der Schichtregel eine pruefbare Zusage statt einer Absicht."""

import ast
from pathlib import Path

import pytest

import pricing

WURZEL = Path(pricing.__file__).parent

# deps.py darf sqlalchemy.orm.Session nennen: FastAPI loest die Annotation
# von SessionDep zur Laufzeit auf, ein TYPE_CHECKING-Import genuegt nicht.
# Session(...) AUFGERUFEN wird nur in bootstrap.py.
AUSNAHME = {("deps.py", "sqlalchemy.orm")}

VERBOTEN_IN_PRESENTATION = (
    "psycopg",
    "sqlalchemy",
    "pricing.persistence.orm",
    "pricing.persistence.repositories",
    "pricing.persistence.api_keys",
    "pricing.persistence.db",
)


def importe(datei: Path) -> set[str]:
    baum = ast.parse(datei.read_text())
    namen: set[str] = set()
    for knoten in ast.walk(baum):
        if isinstance(knoten, ast.Import):
            namen.update(a.name for a in knoten.names)
        elif isinstance(knoten, ast.ImportFrom) and knoten.module:
            if knoten.level:  # relativer Import: auf den vollen Pfad bringen
                teile = datei.relative_to(WURZEL.parent).parent.parts
                basis = teile[: len(teile) - knoten.level + 1]
                modul = ".".join([*basis, knoten.module])
            else:
                modul = knoten.module
            namen.add(modul)
            # "from ..persistence import orm" holt pricing.persistence.orm,
            # nennt als Modul aber nur pricing.persistence.
            namen.update(f"{modul}.{a.name}" for a in knoten.names)
    return namen


def erlaubt(datei: Path, modul: str) -> bool:
    return any(
        modul == a or modul.startswith(a + ".")
        for name, a in AUSNAHME
        if name == datei.name
    )


@pytest.mark.parametrize(
    "datei", sorted((WURZEL / "presentation").rglob("*.py")), ids=lambda p: p.name
)
def test_presentation_nennt_keine_implementierung(datei: Path) -> None:
    for modul in importe(datei):
        for verboten in VERBOTEN_IN_PRESENTATION:
            if modul == verboten or modul.startswith(verboten + "."):
                if erlaubt(datei, modul):
                    continue
                pytest.fail(f"{datei.name} importiert {modul}")


@pytest.mark.parametrize(
    "datei", sorted((WURZEL / "domain").rglob("*.py")), ids=lambda p: p.name
)
def test_domain_kennt_keine_hoehere_schicht(datei: Path) -> None:
    for modul in importe(datei):
        assert not modul.startswith(
            ("pricing.application", "pricing.persistence", "pricing.presentation")
        ), f"{datei.name} importiert {modul}"

