class FakeCapacityRepository:
    """Nur so viel Verhalten, wie die Tests brauchen."""

    def __init__(self) -> None:
        self.zeilen: dict[int, orm.Capacity] = {}
        self.fehler: Exception | None = None

    def list_all(
        self,
        product_id: str | None = None,
        calendar_date: date | None = None,
        limit: int = 50,
        offset: int = 0,
    ) -> Sequence[orm.Capacity]:
        alle = list(self.zeilen.values())
        return alle[offset : offset + limit]

    def get(self, capacity_id: int) -> orm.Capacity | None:
        return self.zeilen.get(capacity_id)

    def create(self, daten: Mapping[str, object]) -> orm.Capacity:
        if self.fehler is not None:
            raise self.fehler
        zeile = orm.Capacity(**daten)
        zeile.id = max(self.zeilen, default=0) + 1
        self.zeilen[zeile.id] = zeile
        return zeile

    def update(
        self, capacity_id: int, daten: Mapping[str, object]
    ) -> orm.Capacity | None:
        zeile = self.zeilen.get(capacity_id)
        if zeile is None:
            return None
        for feld, wert in daten.items():
            setattr(zeile, feld, wert)
        return zeile

    def delete(self, capacity_id: int) -> bool:
        if self.fehler is not None:
            raise self.fehler
        return self.zeilen.pop(capacity_id, None) is not None


class FakeRecommendationRepository:
    def __init__(self) -> None:
        self.zeilen: dict[int, orm.PriceRecommendation] = {}

    def list_all(
        self, limit: int = 50, offset: int = 0
    ) -> Sequence[orm.PriceRecommendation]:
        return list(self.zeilen.values())[offset : offset + limit]

    def get(self, recommendation_id: int) -> orm.PriceRecommendation | None:
        return self.zeilen.get(recommendation_id)

    def get_max(self) -> orm.PriceRecommendation | None:
        return max(
            self.zeilen.values(),
            key=lambda r: r.recommended_adjustment_pct,
            default=None,
        )

    def find_recommendation_id(
        self, product_id: str, calendar_date: date
    ) -> int | None:
        for r in self.zeilen.values():
            if (
                r.capacity.product_id == product_id
                and r.capacity.calendar_date == calendar_date
            ):
                return r.id
        return None


def mach_empfehlung(rid: int, product_id: str, tag: date, pct: str) -> Any:
    kapazitaet = orm.Capacity(
        product_id=product_id, calendar_date=tag, bookable_units=3, optional_units=0
    )
    kapazitaet.id = rid
    empfehlung = orm.PriceRecommendation(
        capacity_id=rid,
        computed_at=datetime.now(UTC),
        days_until_travel=10,
        recommended_adjustment_pct=pct,
        occupancy=1.0,
        total_capacity=3,
        booked_units=3,
    )
    empfehlung.id = rid
    empfehlung.capacity = kapazitaet
    return empfehlung


